import{_ as a}from"./chunks/single-publish.dkGMB9e8.js";import{_ as s,c as e,o as i,ag as l}from"./chunks/framework.3IuuWm4t.js";const k=JSON.parse('{"title":"详细发布","description":"","frontmatter":{},"headers":[],"relativePath":"guide/single-publish.md","filePath":"guide/single-publish.md","lastUpdated":1795234250000}'),r={name:"guide/single-publish.md"};function o(n,t,d,h,p,c){return i(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="详细发布" tabindex="-1">详细发布 <a class="header-anchor" href="#详细发布" aria-label="Permalink to &quot;详细发布&quot;">​</a></h1><p>详细发布把发布前的每一项参数都摊开：标题、摘要、标签、分类、别名、发布时间、状态等，适合需要精细控制的场景。</p><p><img src="'+a+`" alt="详细发布：选择平台" loading="lazy"></p><h2 id="入口" tabindex="-1">入口 <a class="header-anchor" href="#入口" aria-label="Permalink to &quot;入口&quot;">​</a></h2><ul><li>快速发布的平台卡片上点「详细发布」</li><li>文章管理里某篇文档的「单发」</li></ul><h2 id="两步流程" tabindex="-1">两步流程 <a class="header-anchor" href="#两步流程" aria-label="Permalink to &quot;两步流程&quot;">​</a></h2><h3 id="第一步-选择平台" tabindex="-1">第一步：选择平台 <a class="header-anchor" href="#第一步-选择平台" aria-label="Permalink to &quot;第一步：选择平台&quot;">​</a></h3><p>按平台图标选择目标平台。已发布过的平台会标出「预览」，未发布的标「未发布」。</p><h3 id="第二步-编辑发布内容" tabindex="-1">第二步：编辑发布内容 <a class="header-anchor" href="#第二步-编辑发布内容" aria-label="Permalink to &quot;第二步：编辑发布内容&quot;">​</a></h3><table tabindex="0"><thead><tr><th>项</th><th>说明</th></tr></thead><tbody><tr><td>编辑模式</td><td>简洁 / 详细 / 源码三种，按需要切换</td></tr><tr><td>文章标题</td><td>默认取文档标题，可修改，也可点「自动提取标题」</td></tr><tr><td>摘要</td><td>平台未返回时回退到思源笔记的摘要</td></tr><tr><td>标签 / 分类</td><td>平台支持时生效；平台未返回时回退到思源笔记</td></tr><tr><td>知识空间 / 专栏 / 文集</td><td>取决于平台；配置存值，编辑时只读</td></tr><tr><td>别名（slug）</td><td>影响文章链接；文档没生成过时按本次发布结果写回</td></tr><tr><td>图床服务</td><td>按平台分别指定</td></tr><tr><td>图片自动上传</td><td>跟随设置 / 自动上传 / 不自动上传；文章设置优先于目录规则，对所有平台生效，选择后自动保存</td></tr><tr><td>同步修改到思源笔记</td><td>按钮：把当前表单内容写回文档属性（详见下一节）</td></tr></tbody></table><h3 id="「同步修改到思源笔记」会写什么" tabindex="-1">「同步修改到思源笔记」会写什么 <a class="header-anchor" href="#「同步修改到思源笔记」会写什么" aria-label="Permalink to &quot;「同步修改到思源笔记」会写什么&quot;">​</a></h3><p>它<strong>不发布文章</strong>，只把当前编辑页的内容写回思源文档，让下次打开这个页面时可以直接沿用：</p><ul><li><strong>思源自带属性</strong>：摘要（<code>memo</code>）、标签（<code>tags</code>）、分类（<code>custom-categories</code>）</li><li><strong>当前平台的 YAML</strong>：按表单里的标题、摘要、标签、分类、发布时间、更新时间、别名等重新生成，连同永久链接一起写入文档的自定义属性；已发布过的文章下次打开会读回这份 YAML</li><li><strong>不写正文</strong>：正文和图片始终以文档原文为准，图片仍在上传/发布时处理</li></ul><p>几条规则：</p><ul><li>直接点「发布 / 更新」时这些内容同样会写回，不必先点这个按钮</li><li><strong>源码模式</strong>下以编辑框里的 YAML 为准：先点「马上保存」把 YAML 解析进模型，再同步就写回你编辑的那份</li><li>只在表单里改了内容、既不同步也不发布：改动只存在于当前页面，换页后丢失</li></ul><h3 id="源码模式与图片" tabindex="-1">源码模式与图片 <a class="header-anchor" href="#源码模式与图片" aria-label="Permalink to &quot;源码模式与图片&quot;">​</a></h3><p>源码模式显示文档的<strong>原始 Markdown</strong>（图片为本地 <code>assets/</code> 路径），编辑期间不改动文档：</p><ul><li>允许自动上传时，图片的<strong>上传与链接替换统一在发布时执行</strong>；关闭自动上传时保留原图片链接，远端可能无法显示本地图片</li><li>允许自动上传且正文包含图片时，编辑区顶部会给出提示，并可点「<strong>上传并预览替换后的内容</strong>」：立即上传图片并以替换后的结果预览，再点「恢复原文」切回；文章设置或目录规则禁止上传时，只显示「按设置不上传」，不提供上传预览入口</li><li>预览<strong>仅用于查看</strong>，不写入文档；保存与发布始终使用原始内容</li><li>预览适用于「PicGo」与平台自带图床（配置里的「当前平台」）两种方式；图床服务选「不使用」时不提示；批量分发没有单平台上下文，不提供预览</li></ul><p>图片上传的配置步骤与优先级见<a href="./picbed.html#控制图片自动上传">控制图片自动上传</a>。</p><h2 id="yaml-预设配置" tabindex="-1">YAML 预设配置 <a class="header-anchor" href="#yaml-预设配置" aria-label="Permalink to &quot;YAML 预设配置&quot;">​</a></h2><p>静态站点平台的账号配置页提供「YAML 预设配置」，用于为文章的 Front Matter（Markdown 顶部的 YAML 元数据）添加或覆盖字段。填写的是 <strong>JSON 对象</strong>，不是 YAML 文本。</p><p>2.4.0 起，预设的取值支持按当前文章自动填入：</p><ul><li><code>[title]</code>、<code>[slug]</code>：标题、文章别名。</li><li><code>[tags]</code>、<code>[categories]</code>：标签、分类；整个值仅包含该占位符时输出 YAML 数组，嵌在文本中时用逗号连接。</li><li><code>[createDate]</code>、<code>[updateDate]</code>：创建时间、更新时间，默认格式为 <code>YYYY-MM-DD</code>。</li><li><code>[createDate-YYYY-MM-DD HH:mm:ss]</code>、<code>[updateDate-YYYY-MM-DD]</code>：自定义日期格式；没有更新时间时使用创建时间。格式区分大小写。</li></ul><p>例如，为站点自动填写更新时间、标签与分类：</p><div class="language-json vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;updatedDate&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;[updateDate-YYYY-MM-DD]&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;tags&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;[tags]&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;categories&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;[categories]&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>字段名需符合你的站点要求；同名字段会覆盖插件自动生成的值。占位符也可用于嵌套对象、数组中的字符串值；未知占位符保留原样。保存时会校验 JSON 格式，格式不合法时会提示修改。</p><p>这一能力适用于 Astro、Hexo、Hugo、Jekyll、VuePress、VuePress 2、VitePress、Quartz、Docsify 的 YAML 转换，以及相应的 GitLab 平台；预设留空时仍沿用各平台原有默认值。</p><div class="tip custom-block"><p class="custom-block-title">修改预设不会重写已有文章的 YAML</p><p>预设在文章尚未保存该平台 YAML、首次生成时应用。已发布文章的更新沿用文档中已保存的 YAML；需要修改已有文章时，请在详细发布的源码模式编辑 YAML，点「马上保存」后再更新。</p></div><h2 id="可以做的操作" tabindex="-1">可以做的操作 <a class="header-anchor" href="#可以做的操作" aria-label="Permalink to &quot;可以做的操作&quot;">​</a></h2><ul><li><strong>发布 / 更新</strong>：首次发布用「发布」，之后用「更新」</li><li><strong>强制删除</strong>：清理该平台的发布记录</li><li><strong>查看文章</strong>：按「预览地址」模板打开仓库里的 Markdown 源文件；站点上的文章地址由「文章预览规则」写进 Front Matter 的 <code>permalink</code>（Hexo / Quartz 生效），两者不是同一个链接</li></ul><div class="tip custom-block"><p class="custom-block-title">合并模式的例外</p><p>批量分发使用「合并」模式时，标题与摘要的改动不生效（标签与分类会合并）。需要改标题请回到单平台发布操作。</p></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>一次发到多个平台：<a href="./batch-publish.html">批量分发</a></li><li>回看发布记录：<a href="./article-manage.html">文章管理</a></li></ul>`,33)])])}const b=s(r,[["render",o]]);export{k as __pageData,b as default};
